//! # ferrite-ui
//!
//! The screens and the drawing layer under them. Everything draws through [`panel::Panel`] (a window and pixels
//! into it), so the same code runs on the radio's ST7789 and, with the `std` feature, into a frame buffer on the
//! PC ([`fb`]) for the simulator and snapshot tests. Portrait, 240 x 320, RGB565, no frame buffer on the radio.
//!
//! Fonts and the logo are 4-bit masks generated by `tools/mkassets.py` ([`assets`]), each font cut to the
//! characters the UI draws.

#![no_std]

#[cfg(any(test, feature = "std"))]
extern crate std;

pub mod assets;
pub mod boot;
pub mod font4;
pub mod gfx;
pub mod home;
pub mod panel;
pub mod text;
pub mod widgets;

#[cfg(any(test, feature = "std"))]
pub mod fb;
